SELECT jsonb_build_object(
 'relations', (SELECT coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,'acl',ARRAY(SELECT a::text FROM unnest(c.relacl) a ORDER BY a::text COLLATE "C")) ORDER BY c.relname,c.relkind),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','S','v','m','f')),
 'defaults', (SELECT coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'kind',d.defaclobjtype,'acl',ARRAY(SELECT a::text FROM unnest(d.defaclacl) a ORDER BY a::text COLLATE "C")) ORDER BY pg_get_userbyid(d.defaclrole),n.nspname,d.defaclobjtype),'[]'::jsonb) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE n.nspname='public' OR d.defaclnamespace=0),
 'schema', (SELECT jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',ARRAY(SELECT a::text FROM unnest(nspacl) a ORDER BY a::text COLLATE "C"))) FROM pg_namespace WHERE nspname='public'),
 'policies', (SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.tablename,p.policyname),'[]'::jsonb) FROM pg_policies p WHERE p.schemaname='public'),
 'roles', (SELECT jsonb_agg(jsonb_build_object('rolname',rolname,'rolsuper',rolsuper,'rolinherit',rolinherit,'rolcanlogin',rolcanlogin,'rolbypassrls',rolbypassrls) ORDER BY rolname) FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')),
 'memberships', (SELECT coalesce(jsonb_agg(jsonb_build_object('granted_role',parent.rolname,'member',child.rolname,'admin_option',m.admin_option) ORDER BY parent.rolname,child.rolname),'[]'::jsonb) FROM pg_auth_members m JOIN pg_roles parent ON parent.oid=m.roleid JOIN pg_roles child ON child.oid=m.member WHERE child.rolname IN ('anon','authenticated','service_role')),
 'column_grants', (SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'acl',ARRAY(SELECT x::text FROM unnest(a.attacl) x ORDER BY x::text COLLATE "C")) ORDER BY c.relname,a.attname),'[]'::jsonb) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL)
) AS state;
